-- site.db — generated by scripts/model/gen_schema.py (schema v11)
-- application_id 0x534B5701 lets install.sh refuse to open the wrong file.
PRAGMA application_id = 0x534B5701;
PRAGMA user_version = 11;
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

-- The only site-level EAV table. Keys are registry-declared; unknown keys are rejected by the app. Plugin settings do NOT live here (cms_plugin_setting).
CREATE TABLE cms_settings (
  key TEXT PRIMARY KEY CHECK(key GLOB '[a-z0-9._]*'),
  value_json TEXT NOT NULL,
  type TEXT NOT NULL CHECK(type IN ('int','bool','string','json','asset_key')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_by INTEGER
);

-- C-4/C-23: the editor registry IS the loop contract. A `list` row must name exactly one [data-repeat] child and a clamp; a `shell` row is what cms_page.template resolves against; an `island` row owns the prop schema that is validated at save.
CREATE TABLE cms_component_registry (
  name TEXT PRIMARY KEY CHECK(name GLOB '[a-z][a-z0-9-]*' AND length(name) BETWEEN 2 AND 40),
  kind TEXT NOT NULL CHECK(kind IN ('block','shell','island','list')),
  renderer TEXT NOT NULL CHECK(renderer GLOB 'components/*' OR renderer GLOB 'islands/*'),
  repeat_child TEXT,
  bindings_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(bindings_json) AND json_type(bindings_json) = 'array'),
  props_schema_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(props_schema_json) AND json_type(props_schema_json) = 'object'),
  limit_max INTEGER,
  version TEXT NOT NULL,
  CHECK(kind <> 'list' OR (repeat_child IS '[data-repeat]' AND limit_max IS NOT NULL)),
  CHECK(kind = 'list' OR repeat_child IS NULL),
  CHECK(limit_max IS NULL OR limit_max BETWEEN 1 AND 200)
);
CREATE INDEX ix_comp_kind ON cms_component_registry(kind);

-- One document per page: the GrapesJS model is the source of truth, not a block tree. template is a slug resolved against cms_component_registry kind='shell' at publish (no FK: a partial index cannot be an FK parent, make test check 4).
CREATE TABLE cms_page (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  path TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(path = '/' OR (path GLOB '/*' AND path NOT GLOB '*..*' AND path NOT GLOB '*/' AND path NOT GLOB '*//*')),
  slug TEXT NOT NULL CHECK(slug GLOB '[a-z0-9]*' AND slug NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 200),
  status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','hidden')),
  template TEXT NOT NULL DEFAULT 'page' CHECK(template GLOB '[a-z][a-z0-9-]*'),
  body_html TEXT NOT NULL DEFAULT '' CHECK(body_html NOT LIKE '%<script%' AND body_html NOT LIKE '%<style%' AND body_html NOT LIKE '%<!--%' AND body_html NOT LIKE '%javascript:%' AND body_html NOT LIKE '%srcdoc%'),
  body_css TEXT NOT NULL DEFAULT '',
  rev INTEGER NOT NULL DEFAULT 0 CHECK(rev >= 0),
  body_sha TEXT NOT NULL DEFAULT '' CHECK(length(body_sha) IN (0,64)),
  draft_html TEXT NOT NULL DEFAULT '' CHECK(draft_html NOT LIKE '%<script%' AND draft_html NOT LIKE '%<style%' AND draft_html NOT LIKE '%<!--%' AND draft_html NOT LIKE '%javascript:%' AND draft_html NOT LIKE '%srcdoc%'),
  draft_css TEXT NOT NULL DEFAULT '',
  draft_sha TEXT NOT NULL DEFAULT '' CHECK(length(draft_sha) IN (0,64)),
  draft_updated_at TEXT,
  managed_by TEXT NOT NULL DEFAULT 'editor' CHECK(managed_by IN ('editor','hand')),
  seo_json TEXT,
  published_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_by INTEGER
);
CREATE INDEX ix_page_status ON cms_page(status, published_at);

-- Append-only. Covers the designer who hand-edits HTML and breaks it.
CREATE TABLE cms_page_revision (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  page_id INTEGER NOT NULL REFERENCES cms_page(id) ON DELETE CASCADE,
  rev INTEGER NOT NULL DEFAULT 0 CHECK(rev >= 0),
  body_html TEXT NOT NULL,
  body_css TEXT NOT NULL,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER
);
CREATE INDEX ix_rev_page_ts ON cms_page_revision(page_id, created_at);

-- Adjacency list. Position uniqueness uses ifnull() because SQLite treats NULLs as distinct in UNIQUE.
CREATE TABLE cms_nav (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  location TEXT NOT NULL CHECK(location IN ('header','footer','sidebar')),
  parent_id INTEGER REFERENCES cms_nav(id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 80),
  href_kind TEXT NOT NULL DEFAULT 'page' CHECK(href_kind IN ('page','asset','url')),
  href_target TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0 CHECK(position >= 0),
  visible INTEGER NOT NULL DEFAULT 1 CHECK(visible IN (0,1))
);
CREATE UNIQUE INDEX ux_nav_pos ON cms_nav(location, ifnull(parent_id,0), position);

-- Identity is key. sha256 is the physical address and is never referenced by content. storage_path is GENERATED so no form, no driver and no CLI can write it (C-17).
CREATE TABLE cms_asset (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND length(key) BETWEEN 1 AND 96 AND key NOT GLOB '*[^a-z0-9/_.-]*' AND key NOT GLOB '/?*' AND key NOT GLOB '*/' AND key NOT GLOB '*..*' AND key NOT GLOB '.?*'),
  filename TEXT NOT NULL,
  mime TEXT NOT NULL,
  bytes INTEGER NOT NULL CHECK(bytes > 0),
  sha256 TEXT NOT NULL CHECK(length(sha256) = 64),
  kind TEXT NOT NULL CHECK(kind IN ('image','video','audio','document','archive')),
  access_class TEXT NOT NULL DEFAULT 'public' CHECK(access_class IN ('public','linked-private','gated')),
  storage_path TEXT GENERATED ALWAYS AS ('content/media/' || substr(sha256,1,2) || '/' || sha256 || '.' || CASE mime WHEN 'image/webp' THEN 'webp' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/avif' THEN 'avif' WHEN 'application/pdf' THEN 'pdf' WHEN 'video/mp4' THEN 'mp4' WHEN 'audio/mpeg' THEN 'mp3' WHEN 'application/zip' THEN 'zip' ELSE 'bin' END) STORED,
  width INTEGER,
  height INTEGER,
  alt_text TEXT,
  caption TEXT,
  encrypted INTEGER NOT NULL DEFAULT 0 CHECK(encrypted IN (0,1)),
  watermark_asset_id INTEGER REFERENCES cms_asset(id) ON DELETE SET NULL,
  watermark_spec_json TEXT,
  frozen_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER,
  CHECK(kind <> 'image' OR (width IS NOT NULL AND height IS NOT NULL)),
  CHECK(watermark_asset_id IS NULL OR watermark_asset_id <> id),
  CHECK(access_class <> 'public' OR watermark_asset_id IS NULL)
);
CREATE INDEX ix_asset_sha ON cms_asset(sha256);
CREATE INDEX ix_asset_kind ON cms_asset(kind, created_at);

-- Old keys 301 to the live key. Never an FK target. Records unreferenced renames and URL-level renames for keys frozen inside body_html (C-3).
CREATE TABLE cms_asset_alias (
  key TEXT PRIMARY KEY COLLATE NOCASE,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Derived bytes. Not content: no page or user table may reference a variant. storage_path stays stored: it is the only record of which variant files exist on disk.
CREATE TABLE cms_asset_variant (
  id INTEGER PRIMARY KEY,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK(label IN ('thumb','md','lg','og')),
  format TEXT NOT NULL CHECK(format IN ('webp','avif','jpeg','png')),
  width INTEGER NOT NULL,
  height INTEGER NOT NULL,
  bytes INTEGER NOT NULL,
  sha256 TEXT NOT NULL,
  storage_path TEXT NOT NULL,
  CONSTRAINT ux_variant UNIQUE(asset_id, label, format)
);

-- The usage graph. Deletion is refused while a link exists; orphan sweep is an explicit report.
CREATE TABLE cms_asset_link (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  owner_kind TEXT NOT NULL CHECK(owner_kind IN ('page','settings','bundle','datasource')),
  owner_id INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_link UNIQUE(asset_id, owner_kind, owner_id)
);
CREATE INDEX ix_link_owner ON cms_asset_link(owner_kind, owner_id);

-- Sellable set. A code points at an asset or a bundle, never both.
CREATE TABLE cms_asset_bundle (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND key NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Position is unique per bundle so a receipt licence can be ordered.
CREATE TABLE cms_asset_bundle_item (
  bundle_id INTEGER NOT NULL REFERENCES cms_asset_bundle(id) ON DELETE CASCADE,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE RESTRICT,
  position INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(bundle_id, asset_id),
  CONSTRAINT ux_bundle_item_pos UNIQUE(bundle_id, position)
);
CREATE INDEX ix_bundleitem_asset ON cms_asset_bundle_item(asset_id);

-- C-6: a 16-char code is <selector:4><secret:12>. code_selector is plaintext and UNIQUE (the 20-bit index seek); code_hash is argon2id(m=19456,t=2,p=1) over the full 16 characters. There is no pepper and no column holding the secret in recoverable form.
CREATE TABLE cms_download_code (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code_selector TEXT NOT NULL UNIQUE CHECK(length(code_selector) = 4),
  code_hash TEXT NOT NULL CHECK(code_hash GLOB '$argon2id$*'),
  asset_id INTEGER REFERENCES cms_asset(id) ON DELETE RESTRICT,
  bundle_id INTEGER REFERENCES cms_asset_bundle(id) ON DELETE RESTRICT,
  max_uses INTEGER CHECK(max_uses IS NULL OR max_uses BETWEEN 1 AND 100),
  uses INTEGER NOT NULL DEFAULT 0 CHECK(uses >= 0),
  expires_at TEXT,
  issued_to_email TEXT,
  order_ref TEXT,
  revoked_at TEXT,
  last_used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK((asset_id IS NULL) <> (bundle_id IS NULL))
);
CREATE INDEX ix_code_asset ON cms_download_code(asset_id, created_at);

-- O-34: `uses` snapshotted before events are pruned, so the E1 reconciliation still counts a pruned range. v1 never prunes, so this table is empty in every bundle.
CREATE TABLE cms_download_code_archive (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code_id INTEGER NOT NULL REFERENCES cms_download_code(id) ON DELETE CASCADE,
  pruned_through TEXT NOT NULL,
  uses INTEGER NOT NULL CHECK(uses >= 0),
  first_events INTEGER NOT NULL CHECK(first_events >= 0),
  range_events INTEGER NOT NULL DEFAULT 0 CHECK(range_events >= 0),
  archived_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_archive_code ON cms_download_code_archive(code_id, pruned_through);

-- C-7/C-14: the counted unit is the redemption (jti), not the request. bytes_declared is what the app authorised; bytes_sent is filled only from the nginx access log and is NULL in v1. A NOT NULL 0 here would be a fabrication.
CREATE TABLE cms_download_event (
  id INTEGER PRIMARY KEY,
  code_id INTEGER REFERENCES cms_download_code(id) ON DELETE SET NULL,
  asset_id INTEGER REFERENCES cms_asset(id) ON DELETE SET NULL,
  jti TEXT,
  kind TEXT NOT NULL CHECK(kind IN ('first','range','denied')),
  bytes_declared INTEGER NOT NULL CHECK(bytes_declared >= 0),
  bytes_sent INTEGER CHECK(bytes_sent IS NULL OR bytes_sent >= 0),
  ip_hash TEXT,
  ua_hash TEXT,
  outcome TEXT NOT NULL CHECK(outcome IN ('ok','denied_quota','denied_expired','denied_revoked','denied_token','denied_watermark')),
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_ev_code_ts ON cms_download_event(code_id, ts);
CREATE INDEX ix_ev_ts ON cms_download_event(ts);
-- the dedupe gate: one 'first' row per token, many NULLs (a denial against an unknown code has no jti yet)
CREATE UNIQUE INDEX ux_ev_jti_first ON cms_download_event(jti) WHERE kind = 'first';

-- C-16: a bounded transient, not a store. expires_at is token expiry + download.continuation_grace_s; the sweep deletes the file and the row. Class pii in every bundle.
CREATE TABLE cms_watermark_render (
  id INTEGER PRIMARY KEY,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE CASCADE,
  spec_sha TEXT NOT NULL,
  source_sha TEXT NOT NULL,
  bytes INTEGER NOT NULL,
  path TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_wm UNIQUE(spec_sha, source_sha)
);
CREATE INDEX ix_wm_expiry ON cms_watermark_render(expires_at);

-- mode='forward' means the export never emits a dead form.
CREATE TABLE cms_form (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND key NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL,
  fields_json TEXT NOT NULL,
  mode TEXT NOT NULL DEFAULT 'store' CHECK(mode IN ('store','forward','disabled')),
  action_url TEXT,
  notify_email TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK(mode <> 'forward' OR action_url IS NOT NULL)
);

-- Core intake uses the plugin endpoint contract verbatim (O-30): 16 KiB cap, 5/10 min per IP, intent token, honeypot.
CREATE TABLE cms_form_submission (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  form_id INTEGER NOT NULL REFERENCES cms_form(id) ON DELETE CASCADE,
  payload_json TEXT NOT NULL,
  ip_hash TEXT,
  spam_score REAL NOT NULL DEFAULT 0,
  state TEXT NOT NULL DEFAULT 'new' CHECK(state IN ('new','read','spam','forwarded','suppressed')),
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_sub_form_ts ON cms_form_submission(form_id, ts);

-- C-18: kind is view|query only — a `function` source is arbitrary code with a cross-tenant read primitive and is not representable. Aggregates are grammar (aggregate_json + group_by_json), not code. cost_ms_max is the gate (O-14): p95 of 20 is not an estimator.
CREATE TABLE cms_datasource (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND key NOT GLOB '*[^a-z0-9-]*'),
  kind TEXT NOT NULL CHECK(kind IN ('view','query')),
  spec_json TEXT NOT NULL CHECK(json_valid(spec_json)),
  aggregate_json TEXT CHECK(aggregate_json IS NULL OR (json_valid(aggregate_json) AND json_type(aggregate_json) = 'object')),
  group_by_json TEXT CHECK(group_by_json IS NULL OR (json_valid(group_by_json) AND json_type(group_by_json) = 'array')),
  params_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(params_json) AND json_type(params_json) = 'array'),
  is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN (0,1)),
  ttl_s INTEGER NOT NULL DEFAULT 60 CHECK(ttl_s BETWEEN 0 AND 86400),
  cost_ms_p95 REAL CHECK(cost_ms_p95 IS NULL OR cost_ms_p95 >= 0),
  cost_ms_max REAL CHECK(cost_ms_max IS NULL OR cost_ms_max >= 0),
  cost_rows INTEGER,
  cost_measured_at TEXT,
  cost_plan TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  published_at TEXT,
  published_by INTEGER
);
CREATE INDEX ix_ds_public ON cms_datasource(is_public);

-- Views are migration-owned. A view not in this registry fails the DDL runner's postcondition.
CREATE TABLE cms_view_registry (
  name TEXT PRIMARY KEY CHECK(name GLOB 'cms_v_*'),
  checksum TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- C-13: one row per runtime table, with the class/prefix agreement the DDL AST postcondition asserts and the closed-type column inventory Kysely types are regenerated from.
CREATE TABLE cms_table_registry (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  table_name TEXT NOT NULL UNIQUE CHECK(table_name GLOB 'u_?*' OR table_name GLOB 'p_?*'),
  table_class TEXT NOT NULL CHECK(table_class IN ('user','plugin')),
  plugin_id TEXT CHECK(plugin_id IS NULL OR (plugin_id GLOB '[a-z][a-z0-9]*' AND length(plugin_id) BETWEEN 2 AND 20)),
  ddl_version INTEGER NOT NULL DEFAULT 1 CHECK(ddl_version >= 1),
  column_count INTEGER NOT NULL CHECK(column_count BETWEEN 1 AND 40),
  index_count INTEGER NOT NULL DEFAULT 0 CHECK(index_count BETWEEN 0 AND 8),
  columns_json TEXT NOT NULL CHECK(json_valid(columns_json) AND json_type(columns_json) = 'array'),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER,
  notes TEXT,
  CHECK((table_class = 'user' AND table_name GLOB 'u_?*' AND plugin_id IS NULL) OR (table_class = 'plugin' AND table_name GLOB 'p_?*' AND plugin_id IS NOT NULL))
);
CREATE INDEX ix_tbl_class ON cms_table_registry(table_class, plugin_id);

-- Every trigger in the database is registered here; the DDL postcondition is 'every trigger is in this registry', not 'there are zero triggers'.
CREATE TABLE cms_trigger_registry (
  name TEXT PRIMARY KEY,
  table_name TEXT NOT NULL,
  purpose TEXT NOT NULL CHECK(purpose IN ('asset_delete_guard','immutable_column','other')),
  checksum TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_trg_table ON cms_trigger_registry(table_name);

-- C-21: tenant-plane audit, hash-chained inside the tenant's own file. rows are append-only by trigger. prev_hash/hash cover the canonical row; the daily audit_seal in control.db is the anchor that makes deletion visible.
CREATE TABLE cms_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  actor_user_id INTEGER,
  actor_label TEXT NOT NULL,
  action TEXT NOT NULL,
  target_kind TEXT,
  target_id TEXT,
  before_json TEXT,
  after_json TEXT,
  prev_hash TEXT NOT NULL DEFAULT '' CHECK(length(prev_hash) IN (0,64)),
  hash TEXT NOT NULL DEFAULT '' CHECK(length(hash) IN (0,64)),
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_ca_ts ON cms_audit(ts);
CREATE INDEX ix_ca_action ON cms_audit(action, ts);

-- Nobody specified this; every slug rename is a 404 without it. to_path is internal-only: an off-site link is cms_nav.href_kind='url'.
CREATE TABLE cms_redirect (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  from_path TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(from_path = '/' OR (from_path GLOB '/*' AND from_path NOT GLOB '//*' AND from_path NOT GLOB '*..*' AND from_path NOT GLOB '*/' AND from_path NOT GLOB '*//*')),
  to_path TEXT NOT NULL CHECK(to_path = '/' OR (to_path GLOB '/*' AND to_path NOT GLOB '//*' AND to_path NOT GLOB '*..*' AND to_path NOT GLOB '*/' AND to_path NOT GLOB '*//*')),
  status INTEGER NOT NULL DEFAULT 301 CHECK(status IN (301,302,308)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  hits INTEGER NOT NULL DEFAULT 0
);

-- S8s: a stylesheet is a file the browser can cache forever, so it needs a name that is its own bytes. One row per distinct sheet; a row is immutable, because the sha IS the name.
CREATE TABLE cms_css_blob (
  sha256 TEXT PRIMARY KEY CHECK(length(sha256) = 64),
  css TEXT NOT NULL CHECK(length(css) BETWEEN 1 AND 1048576),
  bytes INTEGER NOT NULL CHECK(bytes > 0),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_ccb_created ON cms_css_blob(created_at);

-- S8s: an uploaded look. The CSS lives in cms_css_blob so two identical uploads are one row; `site.theme_key` (cms_settings) names the active one, which is what makes 'only one active at a time' a property of the model rather than a rule someone has to remember.
CREATE TABLE cms_theme (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  theme_key TEXT NOT NULL UNIQUE CHECK(theme_key GLOB '[a-z0-9][a-z0-9-]*' AND length(theme_key) BETWEEN 2 AND 64),
  name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120),
  css_sha256 TEXT NOT NULL REFERENCES cms_css_blob(sha256),
  source_name TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER
);
CREATE INDEX ix_ct_created ON cms_theme(created_at);

-- S8x: a theme is a package, not a stylesheet. The bytes live on disk beside the tenant (`tenants/<key>/theme-assets/<theme_key>/<path>`) and this row is the link the renderer follows: path -> sha, so the URL can be immutable and an export can copy exactly the files a document names. Deleting the theme deletes the rows and the directory.
CREATE TABLE cms_theme_asset (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  theme_id INTEGER NOT NULL REFERENCES cms_theme(id),
  path TEXT NOT NULL CHECK(length(path) BETWEEN 1 AND 200 AND substr(path,1,1) <> '/' AND path NOT GLOB '*..*'),
  sha256 TEXT NOT NULL CHECK(length(sha256) = 64),
  bytes INTEGER NOT NULL CHECK(bytes > 0),
  content_type TEXT NOT NULL CHECK(length(content_type) BETWEEN 3 AND 100),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT uq_cta_path UNIQUE(theme_id, path)
);
CREATE INDEX ix_cta_theme ON cms_theme_asset(theme_id);

-- C-5/C-9: the installed manifest is the ONLY source of a p_* table's export class and of the capability list shown at install. signature_state first_party = our key in the image; imported = the tenant owner imported a publisher key; no CA exists.
CREATE TABLE cms_plugin_installed (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  plugin_id TEXT NOT NULL UNIQUE CHECK(plugin_id GLOB '[a-z][a-z0-9]*' AND length(plugin_id) BETWEEN 2 AND 20),
  version TEXT NOT NULL,
  manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),
  root_hash TEXT NOT NULL CHECK(length(root_hash) = 64),
  publisher TEXT NOT NULL,
  publisher_key_fingerprint TEXT,
  signature_state TEXT NOT NULL CHECK(signature_state IN ('first_party','imported','unsigned')),
  enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),
  test_report_sha TEXT,
  runner_image_digest TEXT,
  installed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  enabled_at TEXT,
  activation_seq INTEGER NOT NULL DEFAULT 0 CHECK(activation_seq >= 0),
  CHECK(publisher_key_fingerprint IS NULL OR length(publisher_key_fingerprint) BETWEEN 16 AND 128),
  CHECK(enabled = 0 OR test_report_sha IS NOT NULL)
);
CREATE INDEX ix_plugin_enabled ON cms_plugin_installed(enabled);

-- The migration ledger the host executor writes. Forward-only, one row per applied (plugin, version, seq).
CREATE TABLE cms_plugin_migration (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  plugin_id TEXT NOT NULL CHECK(plugin_id GLOB '[a-z][a-z0-9]*'),
  version TEXT NOT NULL,
  seq INTEGER NOT NULL CHECK(seq >= 1),
  checksum TEXT NOT NULL,
  duration_ms INTEGER,
  applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_plugin_mig UNIQUE(plugin_id, version, seq)
);

-- O-44: plugin settings live in core, not in plugin tables, so a secret can be made write-only in one place. secret=1 is excluded from every bundle by the projection filter and never returned by settings.get.
CREATE TABLE cms_plugin_setting (
  plugin_id TEXT NOT NULL REFERENCES cms_plugin_installed(plugin_id) ON DELETE CASCADE,
  key TEXT NOT NULL CHECK(key GLOB '[a-z][a-z0-9._-]*'),
  value_json TEXT NOT NULL,
  type TEXT NOT NULL CHECK(type IN ('string','int','bool','json','secret')),
  secret INTEGER NOT NULL DEFAULT 0 CHECK(secret IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_by INTEGER,
  PRIMARY KEY(plugin_id, key),
  CHECK((type = 'secret') = (secret = 1))
);

-- C-9: revocation is local to the install. A package root listed here cannot be installed or enabled, whatever its signature says.
CREATE TABLE cms_plugin_revoked (
  root_hash TEXT PRIMARY KEY CHECK(length(root_hash) = 64),
  plugin_id TEXT NOT NULL,
  reason TEXT,
  revoked_by INTEGER,
  revoked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- S9: one row per person who is not an operator. Identity lives in the TENANT's file, never in control.db, so a public registration path can never share a table with the fleet's operator accounts — different cookie, different path, different database. Argon2id at the same cost as an operator password; TOTP is NOT NULL because OTP is mandatory here, not an option; `status` starts at pending and the two CHECKs below make 'active' unrepresentable without a verified address and a confirmed second factor.
CREATE TABLE cms_account (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL COLLATE NOCASE CHECK(email LIKE '%_@_%.__%'),
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended','closed')),
  password_hash TEXT NOT NULL CHECK(length(password_hash) BETWEEN 20 AND 400),
  totp_secret TEXT NOT NULL CHECK(length(totp_secret) BETWEEN 16 AND 128),
  totp_confirmed_at TEXT,
  email_verified INTEGER NOT NULL DEFAULT 0 CHECK(email_verified IN (0,1)),
  failed_logins INTEGER NOT NULL DEFAULT 0 CHECK(failed_logins >= 0),
  locked_until TEXT,
  last_login_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_account_email UNIQUE(email),
  CHECK(status <> 'active' OR email_verified = 1),
  CHECK(status <> 'active' OR totp_confirmed_at IS NOT NULL)
);
CREATE INDEX ix_account_status ON cms_account(status);

-- S9: roles are additive grants, never inferred from each other. A person may be an applicant and an advertiser; the PK refuses a duplicate grant, and the closed vocabulary refuses a role the product does not implement.
CREATE TABLE cms_account_role (
  account_id INTEGER NOT NULL REFERENCES cms_account(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK(role IN ('applicant','advertiser')),
  granted_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY(account_id, role)
);
CREATE INDEX ix_role_role ON cms_account_role(role);

-- S9: email verification and password reset. Only the sha256 is stored — a database copy cannot be replayed to activate an account. Single use is enforced by the conditional UPDATE that sets consumed_at, not by a check-then-write in a handler.
CREATE TABLE cms_account_token (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id INTEGER NOT NULL REFERENCES cms_account(id) ON DELETE CASCADE,
  purpose TEXT NOT NULL CHECK(purpose IN ('verify_email','reset_password')),
  token_hash TEXT NOT NULL CHECK(length(token_hash) = 64),
  expires_at TEXT NOT NULL,
  consumed_at TEXT,
  ip_hash TEXT NOT NULL CHECK(length(ip_hash) = 64),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_account_token_hash UNIQUE(token_hash),
  CHECK(consumed_at IS NULL OR consumed_at >= created_at)
);
CREATE INDEX ix_token_account ON cms_account_token(account_id, purpose);
CREATE INDEX ix_account_token_expiry ON cms_account_token(expires_at);

-- S9: a portal session. The id is 32 random hex bytes, not a token with claims; csrf_secret binds the anti-forgery token to THIS session; ip_hash/ua_hash record the shape it was minted for; rotation is a new row naming the old one in rotated_from, so a stolen id that is rotated away is visible in the table rather than merely absent.
CREATE TABLE cms_account_session (
  id TEXT PRIMARY KEY CHECK(length(id) = 64),
  account_id INTEGER NOT NULL REFERENCES cms_account(id) ON DELETE CASCADE,
  csrf_secret TEXT NOT NULL CHECK(length(csrf_secret) BETWEEN 32 AND 128),
  ip_hash TEXT NOT NULL CHECK(length(ip_hash) = 64),
  ua_hash TEXT NOT NULL CHECK(length(ua_hash) = 64),
  created_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  rotated_from TEXT,
  revoked_at TEXT
);
CREATE INDEX ix_account_session_account ON cms_account_session(account_id);
CREATE INDEX ix_account_session_expiry ON cms_account_session(expires_at);

-- S9: the applicant's own facts — the most sensitive rows this product holds, which is why contact has NO column here. What an advertiser may see is decided by app/accounts/policy.ts, and that function can only return fields of this table, so the projection type has no place to put an address. `visibility` governs discovery and mail only; an application is a separate, deliberate grant. `notify_new_jobs` defaults OFF: visible is necessary and not sufficient for mail. v10: the rate is HOURLY and stored in cents (`hourly_rate_cents`), because the work is bought by the hour and a day is a length nobody states. v11: the arrangement is a SET (`work_modes_json`), because a person may accept on-site AND hybrid AND remote, and the single-word column this replaces could only say one of them; the empty array is the shape a new row starts in and the form refuses it, so a profile that has been saved always names at least one arrangement.
CREATE TABLE cms_profile (
  account_id INTEGER PRIMARY KEY REFERENCES cms_account(id) ON DELETE CASCADE,
  display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 1 AND 120),
  headline TEXT,
  summary TEXT,
  skills_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(skills_json)),
  hourly_rate_cents INTEGER CHECK(hourly_rate_cents IS NULL OR (hourly_rate_cents > 0 AND hourly_rate_cents <= 500000)),
  currency TEXT NOT NULL DEFAULT 'AUD' CHECK(length(currency) = 3),
  availability_days_per_week INTEGER CHECK(availability_days_per_week IS NULL OR availability_days_per_week BETWEEN 1 AND 7),
  location TEXT,
  timezone TEXT,
  work_modes_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(work_modes_json)),
  links_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(links_json)),
  visibility TEXT NOT NULL DEFAULT 'hidden' CHECK(visibility IN ('hidden','discoverable')),
  notify_new_jobs INTEGER NOT NULL DEFAULT 0 CHECK(notify_new_jobs IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_profile_discovery ON cms_profile(visibility, notify_new_jobs);

-- S9: the outbox. `idempotency_key` is UNIQUE so a retried enqueue cannot send twice; one row is one recipient, so a fan-out never needs a Bcc and a reply cannot disclose the list. `status` is the delivery state a worker owns; a suppressed address is recorded once in cms_mail_suppression and never retried.
CREATE TABLE cms_mail (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  to_email TEXT NOT NULL CHECK(to_email LIKE '%_@_%.__%'),
  template TEXT NOT NULL CHECK(length(template) BETWEEN 1 AND 64),
  subject TEXT NOT NULL CHECK(length(subject) BETWEEN 1 AND 200),
  vars_json TEXT NOT NULL CHECK(json_valid(vars_json)),
  status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','sent','failed','suppressed')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts >= 0),
  next_attempt_at TEXT,
  last_error TEXT,
  provider_id TEXT,
  idempotency_key TEXT NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 200),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  sent_at TEXT,
  CONSTRAINT ux_mail_idempotency UNIQUE(idempotency_key)
);
CREATE INDEX ix_mail_queue ON cms_mail(status, next_attempt_at);
CREATE INDEX ix_mail_created ON cms_mail(created_at);

-- S9: addresses the box must never write to again — a hard bounce, a complaint, or the person's own unsubscribe. Checked immediately before the transport call, not only at enqueue, so an opt-out that arrives while a message is queued still holds.
CREATE TABLE cms_mail_suppression (
  email TEXT PRIMARY KEY COLLATE NOCASE CHECK(email LIKE '%_@_%.__%'),
  reason TEXT NOT NULL CHECK(reason IN ('bounce','complaint','unsubscribe','manual')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- S9/v9: an application — one applicant's deliberate act of sharing their profile with ONE advert. It lives in core, not in a p_* table, because a plugin's EndpointRequest carries no actor: a package cannot answer 'may this viewer see this row' and cannot send mail about it. `job_id` is the plugin table's row id and is deliberately NOT a foreign key — the installer DROPs every table a manifest declares, so a core table that referenced one would be uninstallable. The two account columns are the two grants; `advertiser_account_id` is derived at apply time from the job's company owner and never from a request field. UNIQUE(job_id, applicant_account_id) is what makes a second application the same application rather than a duplicate, and `applicant <> advertiser` is what stops a person applying to their own advert. v11: the `outcome_*` group is the ADVERTISER'S DECISION, recorded beside the applicant's lifecycle `status` rather than as a transition of it — 'submitted'/'withdrawn' say where the application is, `outcome` says what the company concluded, and a row can be `submitted` with an outcome of 'shortlisted' because the applicant never withdrew. `outcome_note` is free text from the advertiser and is screened by app/accounts/pii.ts before it is written, because a note the applicant reads is a note that must not carry contact detail; `outcome_by_account_id` names who recorded it.
CREATE TABLE cms_application (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  job_id INTEGER NOT NULL CHECK(job_id > 0),
  advertiser_account_id INTEGER NOT NULL REFERENCES cms_account(id) ON DELETE CASCADE,
  applicant_account_id INTEGER NOT NULL REFERENCES cms_account(id) ON DELETE CASCADE,
  cover_note TEXT CHECK(cover_note IS NULL OR length(cover_note) BETWEEN 1 AND 4000),
  status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','withdrawn','shortlisted','rejected')),
  outcome TEXT CHECK(outcome IS NULL OR outcome IN ('shortlisted','interview','offer','rejected')),
  outcome_note TEXT CHECK(outcome_note IS NULL OR length(outcome_note) BETWEEN 1 AND 500),
  outcome_at TEXT,
  outcome_by_account_id INTEGER REFERENCES cms_account(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_application UNIQUE(job_id, applicant_account_id),
  CHECK(applicant_account_id <> advertiser_account_id)
);
CREATE INDEX ix_application_job ON cms_application(job_id, status);
CREATE INDEX ix_application_advertiser ON cms_application(advertiser_account_id, status);
CREATE INDEX ix_application_applicant ON cms_application(applicant_account_id, created_at);

-- Triggers. In-database integrity: they fire for any driver, with foreign_keys OFF,
-- and from the sqlite3 CLI. Every one is registered below.
CREATE TRIGGER trg_cms_asset_delete_guard BEFORE DELETE ON cms_asset
WHEN EXISTS (SELECT 1 FROM cms_asset_link        WHERE asset_id = OLD.id)
  OR EXISTS (SELECT 1 FROM cms_asset_bundle_item WHERE asset_id = OLD.id)
  OR EXISTS (SELECT 1 FROM cms_download_code     WHERE asset_id = OLD.id)
BEGIN
  SELECT RAISE(ABORT, 'SKW_E_DM_ASSET_IN_USE');
END;
INSERT INTO cms_trigger_registry(name, table_name, purpose, checksum)
  VALUES ('trg_cms_asset_delete_guard', 'cms_asset', 'asset_delete_guard', 'v3');

CREATE TRIGGER trg_cms_asset_sha_immutable BEFORE UPDATE OF sha256 ON cms_asset
WHEN NEW.sha256 IS NOT OLD.sha256
BEGIN
  SELECT RAISE(ABORT, 'SKW_E_DM_COLUMN_IMMUTABLE');
END;
INSERT INTO cms_trigger_registry(name, table_name, purpose, checksum)
  VALUES ('trg_cms_asset_sha_immutable', 'cms_asset', 'immutable_column', 'v3');

CREATE TRIGGER trg_cms_download_code_hash_immutable BEFORE UPDATE OF code_hash, code_selector ON cms_download_code
WHEN NEW.code_hash IS NOT OLD.code_hash OR NEW.code_selector IS NOT OLD.code_selector
BEGIN
  SELECT RAISE(ABORT, 'SKW_E_DM_COLUMN_IMMUTABLE');
END;
INSERT INTO cms_trigger_registry(name, table_name, purpose, checksum)
  VALUES ('trg_cms_download_code_hash_immutable', 'cms_download_code', 'immutable_column', 'v3');

CREATE TRIGGER trg_cms_audit_append_only BEFORE UPDATE ON cms_audit
BEGIN
  SELECT RAISE(ABORT, 'SKW_E_DM_COLUMN_IMMUTABLE');
END;
INSERT INTO cms_trigger_registry(name, table_name, purpose, checksum)
  VALUES ('trg_cms_audit_append_only', 'cms_audit', 'immutable_column', 'v3');

CREATE TRIGGER trg_cms_audit_no_delete BEFORE DELETE ON cms_audit
BEGIN
  SELECT RAISE(ABORT, 'SKW_E_DM_COLUMN_IMMUTABLE');
END;
INSERT INTO cms_trigger_registry(name, table_name, purpose, checksum)
  VALUES ('trg_cms_audit_no_delete', 'cms_audit', 'immutable_column', 'v3');

-- u_* tables are created at runtime by the DDL runner and p_<id>_* by the plugin
-- migration executor; neither class is declared here.

